/// The only mandatory item in the @fields dictionary is the `"MESSAGE"` which must
/// contain the text shown to the user.
///
/// The values in the @fields dictionary are likely to be of type `G_VARIANT_TYPE_STRING`.
/// Array of bytes (`G_VARIANT_TYPE_BYTESTRING`) is also
/// supported. In this case the message is handled as binary and will be forwarded
/// to the log writer as such. The size of the array should not be higher than
/// `G_MAXSSIZE`. Otherwise it will be truncated to this size. For other types
/// [method@GLib.Variant.print] will be used to convert the value into a string.
///
/// For more details on its usage and about the parameters, see [func@GLib.log_structured].
final _gLogVariant =
    girGlibLookup<
          ffi.NativeFunction<
            ffi.Void Function(
              ffi.Pointer<Utf8>,
              ffi.Uint32,
              ffi.Pointer<ffi.Void>,
            )
          >
        >('g_log_variant')
        .asFunction<
          void Function(ffi.Pointer<Utf8>, int, ffi.Pointer<ffi.Void>)
        >();
void logVariant(String? logDomain, GLogLevelFlags logLevel, GVariant fields) {
  withNativeString(logDomain, (nativeLogDomain) {
    _gLogVariant(nativeLogDomain.cast<Utf8>(), logLevel.value, fields.handle);
  });
}
